echo "dynamic ".count($index->dynamicReferences())."\n";
$byKind = [];
foreach ($index->references() as $r) {
    $byKind[$r['kind']] = ($byKind[$r['kind']] ?? 0) + 1;
}
ksort($byKind);
foreach ($byKind as $k => $n) echo "kind $k $n\n";

$methods = [];
$filesOf = [];
foreach ($index->declarations() as $d) {
    $filesOf[$d['fqcn']] = $d['file'];
    foreach ($d['methods'] as $m) {
        $methods[$d['fqcn'].'::'.$m['name']] = true;
    }
}
$dups = [];
$seen = [];
foreach ($index->declarations() as $d) {
    if (isset($seen[$d['fqcn']])) $dups[$d['fqcn']][] = $d['file'];
    else $seen[$d['fqcn']] = $d['file'];
}
echo "duplicate fqcns ".count($dups)."\n";
foreach (array_slice($dups, 0, 10, true) as $fqcn => $files) {
    echo "  dup $fqcn also ".implode(' ', (array)$files)." first {$seen[$fqcn]}\n";
}

$bad = [];
foreach ([...$index->references(), ...$index->dynamicReferences()] as $r) {
    if (!str_contains($r['symbol'], '::')) continue;
    if (!isset($methods[$r['symbol']])) {
        $bad[$r['symbol']] = ($bad[$r['symbol']] ?? 0) + 1;
    }
}
arsort($bad);
echo "symbols whose method is not declared: ".count($bad)."\n";
$i = 0;
foreach ($bad as $sym => $n) {
    echo "  $n $sym\n";
    if (++$i >= 40) break;
}

echo "\n-- config targets not containing a dot, or attribute-like --\n";
$configs = [];
foreach ($index->references('config') as $r) {
    $configs[$r['target']][] = $r['file'].' @ '.$r['symbol'];
}
ksort($configs);
foreach ($configs as $target => $where) {
    if (!str_contains($target, '.') || str_contains($target, 'request') || !str_contains($target, 'vaulter')) {
        echo "CFG $target\n";
        foreach (array_slice(array_unique($where), 0, 4) as $w) echo "    $w\n";
    }
